--
-- Table structure for table `courses`
--

DROP TABLE IF EXISTS `courses`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `courses` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `instructor_id` bigint(20) unsigned NOT NULL,
  `category_id` bigint(20) unsigned NOT NULL,
  `title` varchar(255) NOT NULL,
  `subtitle` varchar(255) DEFAULT NULL,
  `slug` varchar(255) NOT NULL,
  `short_description` varchar(500) NOT NULL,
  `description` longtext NOT NULL,
  `learning_objectives` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`learning_objectives`)),
  `requirements` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`requirements`)),
  `target_audience` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`target_audience`)),
  `thumbnail` varchar(255) DEFAULT NULL,
  `promotional_video_path` varchar(255) DEFAULT NULL,
  `level` enum('beginner','intermediate','advanced') NOT NULL,
  `language` varchar(50) NOT NULL DEFAULT 'English',
  `duration` int(10) unsigned NOT NULL DEFAULT 0 COMMENT 'Duration in minutes',
  `price` decimal(10,2) NOT NULL DEFAULT 0.00,
  `currency` char(3) NOT NULL DEFAULT 'USD',
  `type` enum('free','paid') NOT NULL,
  `status` enum('draft','pending_review','published','rejected','archived') NOT NULL DEFAULT 'draft',
  `reviewed_by` bigint(20) unsigned DEFAULT NULL,
  `reviewed_at` timestamp NULL DEFAULT NULL,
  `rejection_reason` varchar(255) DEFAULT NULL,
  `published_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `courses_slug_unique` (`slug`),
  KEY `courses_category_id_foreign` (`category_id`),
  KEY `courses_reviewed_by_foreign` (`reviewed_by`),
  KEY `courses_status_category_id_index` (`status`,`category_id`),
  KEY `courses_instructor_id_status_index` (`instructor_id`,`status`),
  KEY `courses_type_price_index` (`type`,`price`),
  KEY `courses_level_index` (`level`),
  KEY `courses_language_index` (`language`),
  KEY `courses_type_index` (`type`),
  KEY `courses_status_index` (`status`),
  KEY `courses_status_published_at_index` (`status`,`published_at`),
  CONSTRAINT `courses_category_id_foreign` FOREIGN KEY (`category_id`) REFERENCES `categories` (`id`),
  CONSTRAINT `courses_instructor_id_foreign` FOREIGN KEY (`instructor_id`) REFERENCES `users` (`id`),
  CONSTRAINT `courses_reviewed_by_foreign` FOREIGN KEY (`reviewed_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=40 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `courses`
--

LOCK TABLES `courses` WRITE;
/*!40000 ALTER TABLE `courses` DISABLE KEYS */;
INSERT INTO `courses` VALUES (1,3,1,'Modern Web Development',NULL,'modern-web-development','Learn the foundations of accessible, responsive web applications.','Learn the foundations of accessible, responsive web applications. This course combines concise explanations, guided examples, and practical activities so learners can apply each concept with confidence.',NULL,NULL,NULL,NULL,NULL,'beginner','English',180,0.00,'USD','free','published',3,'2026-07-14 18:46:34',NULL,'2026-07-14 18:46:34','2026-07-14 18:41:48','2026-07-14 18:46:34'),(2,5,1,'Laravel API Development',NULL,'laravel-api-development','Design secure and maintainable REST APIs with Laravel.','Design secure and maintainable REST APIs with Laravel. This course combines concise explanations, guided examples, and practical activities so learners can apply each concept with confidence.',NULL,NULL,NULL,NULL,NULL,'intermediate','English',240,0.00,'USD','free','published',3,'2026-07-14 18:46:34',NULL,'2026-07-14 18:46:34','2026-07-14 18:41:48','2026-07-14 18:46:34'),(3,3,2,'Digital Marketing Essentials',NULL,'digital-marketing-essentials','Plan effective digital campaigns using measurable strategies.','Plan effective digital campaigns using measurable strategies. This course combines concise explanations, guided examples, and practical activities so learners can apply each concept with confidence.',NULL,NULL,NULL,NULL,NULL,'beginner','English',150,0.00,'USD','free','published',3,'2026-07-14 18:46:34',NULL,'2026-07-14 18:46:34','2026-07-14 18:41:48','2026-07-14 18:46:34'),(4,5,2,'Project Management Fundamentals',NULL,'project-management-fundamentals','Organize teams, scope, schedules, risks, and delivery.','Organize teams, scope, schedules, risks, and delivery. This course combines concise explanations, guided examples, and practical activities so learners can apply each concept with confidence.',NULL,NULL,NULL,NULL,NULL,'beginner','English',165,0.00,'USD','free','published',3,'2026-07-14 18:46:34',NULL,'2026-07-14 18:46:34','2026-07-14 18:41:48','2026-07-14 18:46:34'),(5,3,3,'UI UX Design Foundations',NULL,'ui-ux-design-foundations','Apply research, hierarchy, accessibility, and interaction principles.','Apply research, hierarchy, accessibility, and interaction principles. This course combines concise explanations, guided examples, and practical activities so learners can apply each concept with confidence.',NULL,NULL,NULL,NULL,NULL,'beginner','English',190,0.00,'USD','free','published',3,'2026-07-14 18:46:34',NULL,'2026-07-14 18:46:34','2026-07-14 18:41:48','2026-07-14 18:46:34'),(6,25,4,'Professional English Communication',NULL,'professional-english-communication','Communicate clearly in meetings, presentations, email, and interviews.','<h2>About Professional English Communication</h2><p>Communicate clearly in meetings, presentations, email, and interviews.</p><h3>What you will learn</h3><ul><li>Apply the essential concepts through guided practice.</li><li>Complete realistic exercises and make informed technical decisions.</li><li>Build a repeatable workflow you can use in professional projects.</li><li>Evaluate your understanding through lesson quizzes.</li></ul><h3>Requirements</h3><ul><li>A computer with a modern browser and internet access.</li><li>No specialist experience is required unless the course is marked advanced.</li><li>Curiosity and time to complete the practical exercises.</li></ul>',NULL,NULL,NULL,'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?auto=format&fit=crop&w=1200&q=80',NULL,'intermediate','English',300,0.00,'USD','free','published',19,'2026-07-22 16:58:52',NULL,'2026-07-22 16:58:52','2026-07-14 18:41:48','2026-07-22 16:58:52'),(20,20,1,'Python Programming: Zero to Projects',NULL,'python-programming-zero-to-projects','Master Python syntax, functions, data structures, testing, and practical automation.','<h2>About Python Programming: Zero to Projects</h2><p>Master Python syntax, functions, data structures, testing, and practical automation.</p><h3>What you will learn</h3><ul><li>Apply the essential concepts through guided practice.</li><li>Complete realistic exercises and make informed technical decisions.</li><li>Build a repeatable workflow you can use in professional projects.</li><li>Evaluate your understanding through lesson quizzes.</li></ul><h3>Requirements</h3><ul><li>A computer with a modern browser and internet access.</li><li>No specialist experience is required unless the course is marked advanced.</li><li>Curiosity and time to complete the practical exercises.</li></ul>',NULL,NULL,NULL,'https://images.unsplash.com/photo-1526379095098-d400fd0bf935?auto=format&fit=crop&w=1200&q=80',NULL,'beginner','English',420,0.00,'USD','free','published',19,'2026-07-22 16:58:51',NULL,'2026-07-22 16:58:51','2026-07-22 16:57:19','2026-07-22 16:58:51'),(21,21,1,'Clean Code and Software Design',NULL,'clean-code-and-software-design','Write maintainable code using refactoring, design principles, and effective tests.','<h2>About Clean Code and Software Design</h2><p>Write maintainable code using refactoring, design principles, and effective tests.</p><h3>What you will learn</h3><ul><li>Apply the essential concepts through guided practice.</li><li>Complete realistic exercises and make informed technical decisions.</li><li>Build a repeatable workflow you can use in professional projects.</li><li>Evaluate your understanding through lesson quizzes.</li></ul><h3>Requirements</h3><ul><li>A computer with a modern browser and internet access.</li><li>No specialist experience is required unless the course is marked advanced.</li><li>Curiosity and time to complete the practical exercises.</li></ul>',NULL,NULL,NULL,'https://images.unsplash.com/photo-1515879218367-8466d910aaa4?auto=format&fit=crop&w=1200&q=80',NULL,'intermediate','English',360,39.00,'USD','paid','published',19,'2026-07-22 16:58:51',NULL,'2026-07-22 16:58:51','2026-07-22 16:57:20','2026-07-22 16:58:51'),(22,22,12,'Modern HTML, CSS and JavaScript',NULL,